INSERT INTO `products` VALUES (1,2,'IM-LEN-21EY000LCL','21EY000LCL','LEN-21EY000LCL','Lenovo ThinkPad E14 Gen 5 Core i7 16GB 512GB SSD 14\" FHD IPS Win 11 Pro','lenovo-thinkpad-e14-gen-5-core-i7-16gb-512gb-ssd-14-fhd-ips-win-11-pro-len-21ey000lcl','Lenovo','Notebook empresarial de alta resistencia militar MIL-SPEC con procesador Intel Core i7 de 13ª generación y lector de huellas.','<p>El notebook Lenovo ThinkPad E14 Gen 5 está diseñado para empresas y profesionales que exigen fiabilidad y potencia. Cuenta con procesador Intel Core i7-1355U de 10 núcleos, 16GB de memoria DDR4 y un veloz SSD M.2 PCIe NVMe de 512GB.</p><h5>Rendimiento y Durabilidad Certificada</h5><p>Sometido a rigurosas pruebas de grado militar MIL-STD 810H contra caídas, polvo y temperaturas extremas. Su pantalla de 14 pulgadas FHD antirreflejo garantiza horas de confort visual.</p>','{\"Pantalla\": \"14\\\" FHD (1920x1080) IPS 300 nits Antirreflejo\", \"Garantía\": \"3 años On-Site oficial Lenovo\", \"Gráficos\": \"Intel Iris Xe Graphics integrados\", \"Seguridad\": \"Chip TPM 2.0, Lector de Huella en botón de encendido\", \"Procesador\": \"Intel Core i7-1355U (hasta 5.0 GHz, 10 núcleos)\", \"Memoria RAM\": \"16 GB DDR4-3200 (expandible a 40 GB)\", \"Almacenamiento\": \"512 GB SSD M.2 2242 PCIe 4.0x4 NVMe\", \"Sistema Operativo\": \"Windows 11 Pro 64-bit Español\"}','[{\"answer\": \"Sí, viene con licencia original de Windows 11 Pro OEM lista para unirse a dominios corporativos o Azure Active Directory.\", \"question\": \"¿Viene con Windows 11 Pro activado?\"}, {\"answer\": \"Sí, cuenta con un slot SODIMM libre para ampliar la memoria hasta un total de 40 GB.\", \"question\": \"¿Es posible ampliar la memoria RAM?\"}]',820.00,791300.00,15.00,910000.00,910000.00,NULL,13,'in_stock','https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?w=800&auto=format&fit=crop&q=80','[\"https://ac-resources.nyc3.cdn.digitaloceanspaces.com/images/products/20241206_160603_1.png\", \"https://cdnx.jumpseller.com/n