\n',NULL,NULL,12652.50,12209662.50,NULL,14407400.00,14407400.00,NULL,1,'in_stock','https://media.solotodo.com/media/products/2180249.jpg',NULL,'solotodo','found','2026-10-02 20:47:53',0,1,NULL,NULL,'2026-09-29 05:56:36','2026-10-02 20:47:53'),(1353,7,'6826052','21UY00GKCL','6826052','THINKBOOK 14 G9 IRL I5 210H 16GB 512GB','thinkbook-14-g9-irl-i5-210h-16gb-512gb-6826052','Lenovo','Lenovo ThinkBook 14 G9 IRL, Intel Core 5, 2,2 GHz, 35,6 cm (14\"), 1920 x 1200 Pixeles, 16 GB, 512 GB','<p>Lenovo ThinkBook 14 G9 IRL. Tipo de producto: Portátil, Factor de forma: Concha. Familia de procesador: Intel Core 5, Modelo del procesador: 210H, Frecuencia del procesador: 2,2 GHz. Diagonal de la pantalla: 35,6 cm (14\"), Tipo HD: WUXGA, Resolución de la pantalla: 1920 x 1200 Pixeles. Memoria interna: 16 GB, Tipo de memoria interna: DDR5-SDRAM. Capacidad total de almacenaje: 512 GB, Unidad de almacenamiento: SSD. Modelo de adaptador gráfico incorporado: Intel Graphics. Sistema operativo instalado: Windows 11 Pro. Color del producto: Gris</p>','{\"Tipo HD\": \"WUXGA\", \"Factor de forma\": \"Concha\", \"Gama de colores\": \"45%\", \"Nombre del color\": \"Arctic Grey\", \"Pantalla táctil\": \"No\", \"Tipo de pantalla\": \"IPS\", \"Tipo de producto\": \"Portátil\", \"Brillo de pantalla\": \"400 cd / m²\", \"Color del producto\": \"Gris\", \"Espacio de color RGB\": \"NTSC\", \"Familia de procesador\": \"Intel Core 5\", \"Modelo del procesador\": \"210H\", \"Retroiluminación LED\": \"Si\", \"Material de la carcasa\": \"Acrilonitrilo butadieno estireno (ABS), Policarbonato (PC)\", \"Diagonal de la pantalla\": \"35,6 cm (14\\\")\", \"Fabricante de procesador\": \"Intel\", \"Frecuencia del procesador\": \"2,2 GHz\", \"Pantalla antirreflectante\": \"Si\", \"Resolución de la pantalla\": \"1920 x 1200 Pixeles\", \"Relación de aspecto nativa\": \"16:10\", \"Número de hilos de ejecución\": \"12\", \"Frecuencia del procesador turbo\": \"4,8 GHz\", \"Número de núcleos de procesador\": \"8\", \"Mat